import numpy as np
from scipy.optimize import least_squares
from scipy.spatial.transform import Rotation
p=np.array([[.1199,0,.5512],[.1199,-.0054,.6796],[.1199,-.0117,.89],[.1199,-.0181,1.1004],[.1199,-.0245,1.3088],[.1199,-.0247,1.4147],[.1199,-.0249,1.5207],[.1199,-.0249,1.7261]]);a=np.array([[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1]])
def fk(q,jac=False):
 R=np.eye(3);x=p[0].copy();pts=[];axs=[]
 for i in range(7):pts.append(x.copy());axs.append(R@a[i]);R=R@Rotation.from_rotvec(a[i]*q[i]).as_matrix();x+=R@(p[i+1]-p[i])
 if not jac:return x,R
 return x,R,np.stack([np.cross(axs[i],x-pts[i]) for i in range(7)],axis=1)
q0=np.array([-.201,.201,3.224,-1.31,.063,-.484,1.572]);lo=np.array([-6,-2.24,-6,-2.57,-6,-2.09,-6]);hi=-lo
for z in [1.1,1.2,1.3]:
 t=np.array([.8,.08,z]);ss=[]
 for n in range(60):
  seed=q0 if n==0 else np.clip(q0+np.random.default_rng(n+int(z*100)).normal(0,2,7),lo,hi)
  sol=least_squares(lambda q:np.r_[(fk(q)[0]-t)*8,(q-seed)*.005],seed,bounds=(lo,hi),max_nfev=700)
  x,R,J=fk(sol.x,True);err=np.linalg.norm(x-t);score=np.sum(np.abs(J[0,:]))
  if err<.01:ss.append((score,err,sol.x,R[:,2],J[0,:]))
 print('\nZ',z,'valid',len(ss))
 for score,err,q,zd,jx in sorted(ss,key=lambda v:-v[0])[:4]:print(round(score,3),np.round(q,3),'zdir',np.round(zd,2),'Jx',np.round(jx,2))
